import codecs


def decode_nonblank(payload, encodings=("utf-8", "latin-1")):
    if not isinstance(payload, bytes):
        raise ValueError("payload must be bytes")
    if not isinstance(encodings, (list, tuple)) or not encodings:
        raise ValueError("encodings must be a non-empty sequence")
    if any(not isinstance(name, str) or not name for name in encodings):
        raise ValueError("invalid encoding name")
    if len(set(encodings)) != len(encodings):
        raise ValueError("duplicate encoding")
    for name in encodings:
        try:
            codecs.lookup(name)
        except LookupError as error:
            raise ValueError("unknown encoding") from error
    for name in encodings:
        try:
            text = payload.decode(name, errors="strict")
            return tuple(line.strip() for line in text.splitlines() if line.strip())
        except UnicodeDecodeError:
            raise
    return ()
```

